package zw.ac.msu.dzimbahub.config;
import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import zw.ac.msu.dzimbahub.auth.*; import java.util.Locale;
@Configuration public class AdminBootstrap { @Bean CommandLineRunner bootstrapAdmin(AppUserRepository users,PasswordEncoder encoder,@Value("${app.bootstrap-admin.email:}") String email,@Value("${app.bootstrap-admin.password:}") String password){return args->{if(email.isBlank()||password.isBlank())return;if(password.length()<12)throw new IllegalStateException("BOOTSTRAP_ADMIN_PASSWORD must be at least 12 characters.");String normalized=email.trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(normalized))return;AppUser admin=new AppUser("DzimbaHub Administrator",normalized,encoder.encode(password),UserRole.ADMIN);admin.setStatus(AccountStatus.APPROVED);users.save(admin);};}}
